initJs:
function(container, apiUrl, tables) {
  let currentApplyProcess = null;
  let selectedStores = new Set();
  let availableModels = [];
  let currentModelDetails = null;

  // 初期化
  async function init() {
    await loadModels();
    await loadStores();
    setDefaultDateTime();
    setupEventListeners();
  }

  // モデル一覧を読み込み
  async function loadModels() {
    // 検証済みモデルのみを表示（実際のAPIでは検証ステータスでフィルタ）
    availableModels = [
      { id: '1', name: 'AI需要予測モデル v2.1', status: '検証完了', accuracy: 95.2, version: 'v2.1' },
      { id: '2', name: 'AI需要予測モデル v2.0', status: '検証完了', accuracy: 93.8, version: 'v2.0' },
      { id: '3', name: 'AI需要予測モデル v1.9', status: '検証中', accuracy: 92.1, version: 'v1.9' }
    ];

    const modelSelect = container.querySelector('#select-model');
    modelSelect.innerHTML = '<option value="">-- モデルを選択してください --</option>';

    availableModels.filter(m => m.status === '検証完了').forEach(model => {
      const option = document.createElement('option');
      option.value = model.id;
      option.textContent = `${model.name} (精度: ${model.accuracy}%)`;
      modelSelect.appendChild(option);
    });
  }

  // 店舗一覧を読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1) || [];
    const storeList = container.querySelector('#store-list');

    storeList.innerHTML = stores.map(store => `
      <label style="display: block; margin-bottom: 5px; color: var(--text);">
        <input type="checkbox" class="store-checkbox" value="${store.id}">
        ${store.店舗名} (${store.店舗コード})
      </label>
    `).join('');
  }

  // デフォルト日時設定
  function setDefaultDateTime() {
    const now = new Date();
    now.setMinutes(now.getMinutes() + 10); // 10分後をデフォルト
    const datetime = now.toISOString().slice(0, 16);
    container.querySelector('#apply-datetime').value = datetime;
  }

  // イベントリスナー設定
  function setupEventListeners() {
    // モデル選択時
    container.querySelector('#select-model').addEventListener('change', onModelSelect);

    // 全店舗選択
    container.querySelector('#select-all-stores').addEventListener('change', onSelectAllStores);

    // 店舗選択
    container.addEventListener('change', (e) => {
      if (e.target.classList.contains('store-checkbox')) {
        onStoreSelect();
      }
    });

    // 適用実行ボタン
    container.querySelector('#btn-apply').addEventListener('click', onApplyClick);

    // 一括適用ボタン
    container.querySelector('#btn-batch-apply').addEventListener('click', onBatchApplyClick);

    // ロールバックボタン
    container.querySelector('#btn-rollback').addEventListener('click', onRollbackClick);

    // ダイアログ
    container.querySelector('#dialog-ok').addEventListener('click', onDialogOk);
    container.querySelector('#dialog-cancel').addEventListener('click', hideDialog);
  }

  // モデル選択時の処理
  function onModelSelect() {
    const modelId = container.querySelector('#select-model').value;
    const model = availableModels.find(m => m.id === modelId);

    if (model) {
      currentModelDetails = model;
      showModelDetails(model);
      showValidationResults(model);
      updateImpactRange();
    } else {
      hideModelDetails();
      hideValidationResults();
      hideImpactRange();
    }
  }

  // モデル詳細表示
  function showModelDetails(model) {
    const detailsDiv = container.querySelector('#model-details');
    const infoDiv = container.querySelector('#model-info');

    infoDiv.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 15px;">
        <div>
          <strong>モデル名:</strong> ${model.name}<br>
          <strong>バージョン:</strong> ${model.version}<br>
          <strong>検証ステータス:</strong> <span style="color: #4CAF50;">${model.status}</span>
        </div>
        <div>
          <strong>予測精度:</strong> ${model.accuracy}%<br>
          <strong>作成日:</strong> 2024-01-15<br>
          <strong>最終更新:</strong> 2024-01-20
        </div>
      </div>
    `;

    detailsDiv.style.display = 'block';
  }

  // モデル詳細非表示
  function hideModelDetails() {
    container.querySelector('#model-details').style.display = 'none';
  }

  // 検証結果表示
  function showValidationResults(model) {
    const resultsDiv = container.querySelector('#validation-results');
    const infoDiv = container.querySelector('#validation-info');

    infoDiv.innerHTML = `
      <div style="color: #4CAF50; margin-bottom: 10px;">✓ 検証完了</div>
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 15px;">
        <div>
          <strong>テストデータ精度:</strong> ${model.accuracy}%<br>
          <strong>検証期間:</strong> 2024-01-01 ～ 2024-01-14<br>
          <strong>検証データ件数:</strong> 10,000件
        </div>
        <div>
          <strong>平均誤差率:</strong> 4.8%<br>
          <strong>最大誤差率:</strong> 12.3%<br>
          <strong>検証完了日:</strong> 2024-01-20
        </div>
      </div>
    `;

    resultsDiv.style.display = 'block';
  }

  // 検証結果非表示
  function hideValidationResults() {
    container.querySelector('#validation-results').style.display = 'none';
  }

  // 全店舗選択
  function onSelectAllStores() {
    const selectAll = container.querySelector('#select-all-stores').checked;
    const checkboxes = container.querySelectorAll('.store-checkbox');

    checkboxes.forEach(cb => {
      cb.checked = selectAll;
    });

    onStoreSelect();
  }

  // 店舗選択時の処理
  function onStoreSelect() {
    const checkboxes = container.querySelectorAll('.store-checkbox:checked');
    selectedStores.clear();

    checkboxes.forEach(cb => {
      selectedStores.add(cb.value);
    });

    updateImpactRange();
  }

  // 影響範囲更新
  function updateImpactRange() {
    if (selectedStores.size === 0 || !currentModelDetails) {
      hideImpactRange();
      return;
    }

    const impactDiv = container.querySelector('#impact-range');
    const infoDiv = container.querySelector('#impact-info');

    const estimatedTime = Math.ceil(selectedStores.size * 2); // 1店舗あたり2分と仮定

    infoDiv.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 15px;">
        <div>
          <strong>対象店舗数:</strong> ${selectedStores.size}店舗<br>
          <strong>影響商品カテゴリ:</strong> 全カテゴリ<br>
          <strong>予想処理時間:</strong> 約${estimatedTime}分
        </div>
        <div>
          <strong>影響する予測データ:</strong> 約${selectedStores.size * 1000}件<br>
          <strong>バックアップサイズ:</strong> 約${Math.ceil(selectedStores.size * 0.5)}MB<br>
          <strong>ダウンタイム:</strong> なし
        </div>
      </div>
      ${selectedStores.size > 10 ? '<div style="color: #ff9800; margin-top: 10px;">⚠ 大規模適用のため、処理に時間がかかる場合があります</div>' : ''}
    `;

    impactDiv.style.display = 'block';
  }

  // 影響範囲非表示
  function hideImpactRange() {
    container.querySelector('#impact-range').style.display = 'none';
  }

  // 適用実行
  function onApplyClick() {
    if (!validateInputs()) return;

    showConfirmDialog(
      'モデル本番適用確認',
      `選択したモデルを${selectedStores.size}店舗に適用します。よろしいですか？`,
      () => executeApply(false)
    );
  }

  // 一括適用
  function onBatchApplyClick() {
    if (!validateInputs()) return;

    showConfirmDialog(
      '一括適用確認',
      `選択したモデルを${selectedStores.size}店舗に一括適用します。処理に時間がかかる場合があります。よろしいですか？`,
      () => executeApply(true)
    );
  }

  // 入力値検証
  function validateInputs() {
    const modelId = container.querySelector('#select-model').value;
    const applyDateTime = container.querySelector('#apply-datetime').value;
    const retentionDays = parseInt(container.querySelector('#retention-days').value);

    if (!modelId) {
      alert('適用対象のモデルが選択されていません');
      return false;
    }

    const model = availableModels.find(m => m.id === modelId);
    if (!model || model.status !== '検証完了') {
      alert('検証が完了していないモデルは本番適用できません');
      return false;
    }

    if (selectedStores.size === 0) {
      alert('店舗が選択されていません');
      return false;
    }

    if (!applyDateTime) {
      alert('適用開始日時を入力してください');
      return false;
    }

    const applyDate = new Date(applyDateTime);
    const now = new Date();
    if (applyDate < now) {
      alert('適用日時は現在日時以降を指定してください');
      return false;
    }

    if (retentionDays <= 0) {
      alert('保持期間は1日以上を設定してください');
      return false;
    }

    if (retentionDays === 0) {
      alert('保持期間に0日が設定されています。1日以上を設定してください');
      return false;
    }

    if (currentApplyProcess) {
      alert('既に適用処理が実行中です。処理完了後に再度実行してください。');
      return false;
    }

    return true;
  }

  // 適用実行
  async function executeApply(isBatch) {
    if (currentApplyProcess) {
      alert('既に適用処理が実行中です。処理完了後に再度実行してください。');
      return;
    }

    currentApplyProcess = {
      modelId: container.querySelector('#select-model').value,
      stores: Array.from(selectedStores),
      startTime: new Date(),
      isBatch: isBatch
    };

    showProgress();

    try {
      await simulateApplyProcess();
      showApplySuccess();
      enableRollback();
    } catch (error) {
      showApplyError(error.message);
    } finally {
      currentApplyProcess = null;
    }
  }

  // 適用処理シミュレーション
  async function simulateApplyProcess() {
    const stores = Array.from(selectedStores);
    const totalSteps = stores.length + 2; // 準備 + 各店舗 + 完了
    let currentStep = 0;

    // 準備
    updateProgress(currentStep++, totalSteps, '適用準備中...');
    addLog('適用処理を開始します');
    addLog(`対象モデル: ${currentModelDetails.name}`);
    addLog(`対象店舗数: ${stores.length}店舗`);

    await sleep(1000);

    // 各店舗への適用
    for (let i = 0; i < stores.length; i++) {
      const storeId = stores[i];
      updateProgress(currentStep++, totalSteps, `店舗 ${i + 1}/${stores.length} 適用中...`);
      addLog(`店舗ID: ${storeId} への適用を開始`);

      await sleep(500);

      addLog(`店舗ID: ${storeId} への適用が完了`);
    }

    // 完了
    updateProgress(currentStep++, totalSteps, '適用完了');
    addLog('全店舗への適用が正常に完了しました');
  }

  // 進捗表示
  function showProgress() {
    container.querySelector('#progress-section').style.display = 'block';
    container.querySelector('#result-log-section').style.display = 'block';
    container.querySelector('#result-log').innerHTML = '';
  }

  // 進捗更新
  function updateProgress(current, total, message) {
    const percentage = Math.round((current / total) * 100);
    container.querySelector('#progress-bar').style.width = `${percentage}%`;
    container.querySelector('#progress-text').textContent = `${message} (${percentage}%)`;
  }

  // ログ追加
  function addLog(message) {
    const logDiv = container.querySelector('#result-log');
    const timestamp = new Date().toLocaleTimeString();
    logDiv.innerHTML += `[${timestamp}] ${message}\n`;
    logDiv.scrollTop = logDiv.scrollHeight;
  }

  // 適用成功
  function showApplySuccess() {
    addLog('=== 適用処理が正常に完了しました ===');
    alert(`モデルの本番適用が完了しました。${selectedStores.size}店舗に正常に適用されました。`);
  }

  // 適用エラー
  function showApplyError(message) {
    addLog(`エラー: ${message}`);
    alert(`適用処理中にエラーが発生しました: ${message}`);
  }

  // ロールバック有効化
  function enableRollback() {
    container.querySelector('#btn-rollback').disabled = false;
  }

  // ロールバック実行
  function onRollbackClick() {
    if (!currentApplyProcess && !container.querySelector('#btn-rollback').disabled) {
      showConfirmDialog(
        'ロールバック確認',
        '現在のモデルを以前のバージョンにロールバックします。よろしいですか？',
        executeRollback
      );
    } else {
      alert('適用前のため、ロールバックできません');
    }
  }

  // ロールバック実行
  async function executeRollback() {
    showProgress();
    updateProgress(0, 3, 'ロールバック準備中...');
    addLog('ロールバック処理を開始します');

    await sleep(1000);

    updateProgress(1, 3, 'バックアップから復元中...');
    addLog('バックアップデータから復元しています');

    await sleep(2000);

    updateProgress(2, 3, 'ロールバック完了');
    addLog('ロールバック処理が正常に完了しました');

    updateProgress(3, 3, 'ロールバック完了');
    addLog('=== ロールバック処理が正常に完了しました ===');

    alert('ロールバック処理が正常に完了しました。以前のモデルバージョンが本番環境に適用されています。');

    container.querySelector('#btn-rollback').disabled = true;
  }

  // 確認ダイアログ表示
  function showConfirmDialog(title, message, onConfirm) {
    container.querySelector('#dialog-title').textContent = title;
    container.querySelector('#dialog-message').textContent = message;
    container.querySelector('#confirm-dialog').style.display = 'block';

    container.querySelector('#dialog-ok').onclick = () => {
      hideDialog();
      onConfirm();
    };
  }

  // ダイアログ非表示
  function hideDialog() {
    container.querySelector('#confirm-dialog').style.display = 'none';
  }

  // ダイアログOK
  function onDialogOk() {
    // イベントリスナーで処理
  }

  // スリープ関数
  function sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  // 初期化実行
  init();
}
